/* shift_table_down -- shipped at 1028:019c, 59 bytes.
 *
 * Opens a gap at n by moving entries n..14 of the 6-byte-record table one place UP:
 * entry i+1 takes entry i, from the top down.
 *
 * HAND-CORRECTED, and deliberately not regenerated by tools/port.py: the reconstruction
 * it would come from has the assignment the other way round (`t[i] = t[i + 1]`). The
 * shipped code computes both addresses and hands them to F_SCOPY:
 *
 *     imul ax,ax,6; add ax,0x67c; push SEG; push ax      -- base + (i + 1) * 6
 *     imul ax,ax,6; add ax,0x676; push SEG; push ax      -- base + i * 6
 *     mov cx,6; call far F_SCOPY
 *
 * and the emulator's write log settles which of the two is the destination: for n = 0 the
 * shipped function writes 45 words at SEG24:0x67c..0x6d5, which is base + (i + 1) * 6.
 * It reads the lower address and writes the higher one. docs/findings/ has the argument.
 */
#include "col/globals.h"

void shift_table_down(col_i16 n)
{
    col_i16 i;

    for (i = 14; i >= n; i--)
        g_table6[i + 1] = g_table6[i];
}
